# shellcheck shell=bash
# Shared attribution policy for git hooks and scripts/audit-attribution.sh.
# Sourced, never executed. Git ignores this file as a hook (not a hook name).
# Stays compatible with macOS /bin/bash 3.2 (no mapfile, no ${var,,}).

readonly STUDIO_ALLOWED_NAME="mikeZ98"
readonly STUDIO_ALLOWED_EMAIL="145975972+mikeZ98@users.noreply.github.com"

# AI tools / vendors that must never be credited in commit metadata. Generic words
# ("LLM", "AI") are deliberately absent: "artifacts generated by the LLM" is domain
# language here. AI-*: trailers are caught by their key instead.
readonly STUDIO_AI_TOOLS='claude|anthropic|chatgpt|openai|gpt-?[0-9]|copilot|gemini|bard|cursor|codex|aider|devin|windsurf|codeium|tabnine'

# Case-insensitive ERE matched line by line against commit messages. It targets
# attribution *metadata* (trailers, signatures, footers, vendor addresses) rather
# than bare product names: this repository builds an LLM chat + artifact studio, so a body line such
# as "stream tokens from the OpenAI-compatible provider" is legitimate content.
# Bare "Claude" and "ChatGPT" are banned outright; the literal CLAUDE.md is exempt.
STUDIO_FORBIDDEN_MSG_RE='^[[:space:]]*co-?authored-by[[:space:]]*:'
# Generated-by:, Assisted-by:, AI-Generated:, Made-with: … trailers, whatever the value.
STUDIO_FORBIDDEN_MSG_RE+='|^[[:space:]]*(ai|assisted|generated|made|created|written|authored|produced|powered)[-_ ]?(by|with|using|generated|assisted)?[[:space:]]*:'
# Trailers keyed by an AI tool (Claude-Session:, Copilot-Id:, …).
STUDIO_FORBIDDEN_MSG_RE+="|^[[:space:]]*(${STUDIO_AI_TOOLS})(-[a-z0-9-]+)?[[:space:]]*:"
# Any *-by: trailer (Signed-off-by:, Reviewed-by:, …) crediting an AI tool.
STUDIO_FORBIDDEN_MSG_RE+="|^[[:space:]]*[a-z]+(-[a-z]+)*-by[[:space:]]*:.*(^|[^[:alnum:]])(${STUDIO_AI_TOOLS})([^[:alnum:]]|$)"
# Signatures / footers: "Generated with [Claude Code](…)", "written by ChatGPT", 🤖.
STUDIO_FORBIDDEN_MSG_RE+="|(^|[^[:alnum:]])(generated|created|written|authored|assisted|drafted|produced)[[:space:]]+(with|by|using|via)[[:space:]]+(\\[|the[[:space:]]+|an?[[:space:]]+)?(${STUDIO_AI_TOOLS})([^[:alnum:]]|$)"
STUDIO_FORBIDDEN_MSG_RE+='|🤖|✨[[:space:]]*generated'
# Vendor addresses and links.
STUDIO_FORBIDDEN_MSG_RE+='|noreply@anthropic\.com|@openai\.com|claude\.(ai|com)|chatgpt\.com'
# Names the blueprint bans outright, anywhere in the message.
STUDIO_FORBIDDEN_MSG_RE+='|(^|[^[:alnum:]])(claude|chatgpt)([^[:alnum:]]|$)'
readonly STUDIO_FORBIDDEN_MSG_RE

readonly STUDIO_CONVENTIONAL_RE='^(feat|fix|chore|docs|test|build|ci|refactor|perf|style|revert)(\([a-z0-9._/-]+\))?!?: [^ ].{0,98}$'

studio_err() { printf '\033[31m✖ %s\033[0m\n' "$*" >&2; }
studio_ok() { printf '\033[32m✔ %s\033[0m\n' "$*" >&2; }

# studio_check_identity <role> <name> <email>
studio_check_identity() {
  local role="$1" name="$2" email="$3"
  if [[ "$name" != "$STUDIO_ALLOWED_NAME" || "$email" != "$STUDIO_ALLOWED_EMAIL" ]]; then
    studio_err "$role identity '$name <$email>' violates the sole-contributor invariant."
    studio_err "Expected: '$STUDIO_ALLOWED_NAME <$STUDIO_ALLOWED_EMAIL>'."
    return 1
  fi
}

# studio_check_pending_identities — validate the identities `git commit` is about to
# record. `git var` resolves --author, GIT_AUTHOR_*/GIT_COMMITTER_* overrides and
# every config layer exactly as the commit will.
studio_check_pending_identities() {
  local fail=0 role ident name email
  for role in AUTHOR COMMITTER; do
    if ! ident="$(git var "GIT_${role}_IDENT" 2>/dev/null)"; then
      studio_err "Cannot resolve the $role identity (user.useConfigOnly is set: run 'direnv allow')."
      fail=1
      continue
    fi
    ident="${ident% * *}" # strip "<unix-time> <tz>"
    name="${ident% <*}"
    email="${ident##*<}"
    email="${email%>}"
    studio_check_identity "$role" "$name" "$email" || fail=1
  done
  return "$fail"
}

# studio_clean_message — strip comments and anything below the scissors line
# (`git commit -v` appends the diff there).
studio_clean_message() {
  sed -e '/^# ------------------------ >8 ------------------------$/,$d' -e '/^#/d'
}

# studio_check_message <message-text>
studio_check_message() {
  local msg="$1" hits
  hits="$(sed -E 's/CLAUDE\.md//g' <<<"$msg" | grep -inE "$STUDIO_FORBIDDEN_MSG_RE" || true)"
  if [[ -n "$hits" ]]; then
    studio_err "Commit message contains forbidden AI attribution / co-author metadata:"
    printf '    %s\n' "$hits" >&2
    return 1
  fi
}

# studio_check_subject <first-line>
studio_check_subject() {
  local subject="$1"
  case "$subject" in
    Merge\ * | fixup!\ * | squash!\ * | amend!\ *) return 0 ;;
  esac
  if ! grep -qE "$STUDIO_CONVENTIONAL_RE" <<<"$subject"; then
    studio_err "Subject is not a Conventional Commit (max 100 chars): '$subject'"
    studio_err "Format: <type>(<scope>)?: <summary>   types: feat fix chore docs test build ci refactor perf style revert"
    return 1
  fi
}
